package org.sleepwell.app;

import android.app.Activity;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Draft-only customization until explicit Save. Mandatory Tonight controls are not configurable. */
public final class TonightLayoutActivity extends Activity {
 private List<String> order;private Set<String> visible;private boolean illustration,resumed;private String expected,issue="",request;private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);RecordUi.review(this);TonightLayout.Config saved=TonightLayout.load(this);order=new ArrayList<>(saved.order);visible=new LinkedHashSet<>(saved.visible);illustration=saved.illustration;expected=saved.fingerprint;issue=saved.issue;if(b!=null){ArrayList<String> sorted=b.getStringArrayList("order"),shown=b.getStringArrayList("visible");if(sorted!=null&&sorted.size()==TonightLayout.ROWS.size()&&new HashSet<>(sorted).size()==TonightLayout.ROWS.size()&&sorted.containsAll(TonightLayout.ROWS))order=new ArrayList<>(sorted);if(shown!=null&&TonightLayout.ROWS.containsAll(shown))visible=new LinkedHashSet<>(shown);illustration=b.getBoolean("illustration",illustration);expected=b.getString("expected",expected);issue=b.getString("issue",issue);request=b.getString("request");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
 private void render(){boolean saving=request!=null;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Tonight layout",this::finish);Design.space(body,16);Design.text(body,"Choose optional rows, then arrange their order.",16,500,Design.INK);Design.space(body,10);Design.text(body,"Alarm, tracking and nap safety controls always remain available.",13,400,Design.MUTED);Design.space(body,20);
  for(int n=0;n<order.size();n++){String id=order.get(n);int index=n;LinearLayout group=Design.col(this);Design.pad(group,14,8);group.setBackground(Design.shape(this,Design.SOFT,16));LinearLayout header=Design.row(this);TextView name=Design.text(this,TonightLayout.title(id),16,600,Design.INK);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));Switch show=new Switch(this);show.setContentDescription("Show "+TonightLayout.title(id));Design.styleSwitch(this,show,Design.VIOLET,Design.LINE);show.setChecked(visible.contains(id));show.setEnabled(!saving);show.setOnCheckedChangeListener((v,on)->{if(on)visible.add(id);else visible.remove(id);});header.addView(show,new LinearLayout.LayoutParams(Design.dp(this,56),Design.dp(this,48)));group.addView(header);Design.text(group,TonightLayout.detail(id),12,400,Design.MUTED);
   LinearLayout controls=Design.row(this);controls.setGravity(Gravity.END);View up=Design.iconButton(this,"up","Move "+TonightLayout.title(id)+" up",()->move(index,-1)),down=Design.iconButton(this,"down","Move "+TonightLayout.title(id)+" down",()->move(index,1));up.setEnabled(!saving&&index>0);down.setEnabled(!saving&&index<order.size()-1);controls.addView(up,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));controls.addView(down,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));group.addView(controls);body.addView(group);Design.space(body,10);
  }
  Design.space(body,6);Switch art=Design.toggle(body,"Show bedside illustration","Uses your current Tonight theme",illustration,on->illustration=on);art.setEnabled(!saving);Design.space(body,12);Design.button(body,"Reset draft to default",false,()->{TonightLayout.Config d=TonightLayout.defaults();order=new ArrayList<>(d.order);visible=new LinkedHashSet<>(d.visible);illustration=d.illustration;issue="Default arrangement restored in this draft. Save to apply.";render();}).setEnabled(!saving);
  LinearLayout footer=RecordUi.footer(body);if(!issue.isEmpty())Design.text(footer,issue,13,400,Design.MUTED);if(saving)Design.text(footer,"Saving layout…",13,400,Design.MUTED);Design.button(footer,"Save Tonight layout",true,()->{request=UUID.randomUUID().toString();issue="";render();observe();}).setEnabled(!saving);Design.button(footer,"Cancel",false,this::finish).setEnabled(!saving);
 }
 private void move(int index,int delta){if(request!=null)return;int target=index+delta;if(target<0||target>=order.size())return;Collections.swap(order,index,target);render();}
 private void observe(){if(!resumed||request==null)return;String token=request,fingerprint=expected;List<String> sorted=List.copyOf(order);Set<String> shown=Set.copyOf(visible);boolean art=illustration;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{TonightLayout.save(app,sorted,shown,art,fingerprint,token);return null;});if(!operation.done){main.removeCallbacks(poll);main.postDelayed(poll,100);return;}PlanOperations.forget(token);request=null;if(operation.error!=null){issue=operation.error;render();}else finish();}
 private final Runnable poll=this::observe;
 @Override protected void onResume(){super.onResume();resumed=true;observe();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 @Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putStringArrayList("order",new ArrayList<>(order));b.putStringArrayList("visible",new ArrayList<>(visible));b.putBoolean("illustration",illustration);b.putString("expected",expected);b.putString("issue",issue);b.putString("request",request);}
 @Override protected void onDestroy(){main.removeCallbacks(poll);super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}